CREATE TABLE IF NOT EXISTS economic_business_network_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, related_type text NOT NULL, related_name text NOT NULL, relationship_type text NOT NULL, direction text NOT NULL DEFAULT 'outbound', status text NOT NULL DEFAULT 'reported', confidence numeric, evidence_ref text, notes text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(profile_id,related_type,related_name,relationship_type));